"""Real OS processes, two loopback endpoints, generated bytes only."""
import asyncio
import json
from pathlib import Path
import sys

RELAY = str(Path(__file__).resolve().parents[1] / "scripts/local_transport.py")


async def next_port(process):
    line = await asyncio.wait_for(process.stdout.readline(), 8)
    return json.loads(line)["port"]


def test_stream_survives_launcher_exit_and_preserves_half_close():
    # The launching process owns no sockets. It exits on request while the test
    # client keeps the same connection open. The one-shot relay exits on EOF.
    launch = """
import subprocess,sys
relay = subprocess.Popen([sys.executable,sys.argv[1],sys.argv[2],'--once'],
                         stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,
                         stderr=subprocess.DEVNULL)
try:
    print(relay.stdout.readline().decode().strip(),flush=True)
    if sys.stdin.readline() != 'release\\n':
        relay.terminate()
finally:
    relay.stdout.close()
"""
    async def scenario():
        received = bytearray()
        done = asyncio.Event()
        async def peer(reader, writer):
            try:
                while block := await reader.read(32768):
                    received.extend(block)
                    writer.write(block)
                    await writer.drain()
                writer.write(b"complete")
                await writer.drain()
            finally:
                writer.close()
                await writer.wait_closed()
                done.set()
        async with await asyncio.start_server(peer, "127.0.0.1", 0) as service:
            launcher = await asyncio.create_subprocess_exec(
                sys.executable, "-c", launch, RELAY, str(service.sockets[0].getsockname()[1]),
                stdin=asyncio.subprocess.PIPE, stdout=asyncio.subprocess.PIPE)
            writer = None
            try:
                reader, writer = await asyncio.open_connection("127.0.0.1", await next_port(launcher))
                writer.write(b"before"); await writer.drain()
                assert await reader.readexactly(6) == b"before"
                launcher.stdin.write(b"release\n"); await launcher.stdin.drain()
                assert await launcher.wait() == 0
                block = bytes(range(256)) * 1025
                writer.write(block); await writer.drain()
                writer.write_eof()
                assert await reader.read() == block + b"complete"
                assert bytes(received) == b"before" + block
                await done.wait()
            finally:
                if writer is not None:
                    writer.close()
                    await writer.wait_closed()
                launcher.stdin.close()
                await launcher.wait()
    asyncio.run(asyncio.wait_for(scenario(), 15))


def test_failed_upstream_does_not_terminate_listener_or_mix_connections():
    async def scenario():
        first = await asyncio.start_server(lambda r,w: w.close(), "127.0.0.1", 0)
        upstream_port = first.sockets[0].getsockname()[1]
        first.close(); await first.wait_closed()
        proc = await asyncio.create_subprocess_exec(sys.executable, RELAY, str(upstream_port),
                                                    stdout=asyncio.subprocess.PIPE)
        try:
            port = await next_port(proc)
            bad, writer = await asyncio.open_connection("127.0.0.1", port)
            assert await bad.read() == b""
            writer.close(); await writer.wait_closed()
            async def ack(reader, writer):
                writer.write(b"ready"); await writer.drain()
                writer.close(); await writer.wait_closed()
            async with await asyncio.start_server(ack, "127.0.0.1", upstream_port):
                good, writer = await asyncio.open_connection("127.0.0.1", port)
                writer.write_eof()
                assert await good.read() == b"ready"
                writer.close(); await writer.wait_closed()
        finally:
            if proc.returncode is None: proc.terminate()
            await proc.wait()
    asyncio.run(asyncio.wait_for(scenario(), 15))
